    RED["RED<br/>Тест падает<br/>по ожидаемой причине"] --> GREEN["GREEN<br/>Реализация<br/>до зелёного"]
    GREEN --> REFACTOR["REFACTOR<br/>Улучшить структуру<br/>сохранив поведение"]
    REFACTOR --> RED
